-- MySQL schema for the Adaptive IDS (generated by scripts/04_init_db.py --print-sql)
CREATE DATABASE IF NOT EXISTS adaptive_ids CHARACTER SET utf8mb4; USE adaptive_ids;
CREATE TABLE IF NOT EXISTS model_versions (
        version VARCHAR(32) PRIMARY KEY, algorithm VARCHAR(64), trigger_type VARCHAR(32), parent_version VARCHAR(32),
        status VARCHAR(16), created_at VARCHAR(24), train_rows BIGINT, metrics_json LONGTEXT, notes LONGTEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS predictions (
        id BIGINT AUTO_INCREMENT PRIMARY KEY, ts VARCHAR(24) NOT NULL, model_version VARCHAR(32), predicted_label VARCHAR(64) NOT NULL,
        is_attack TINYINT NOT NULL, confidence DOUBLE, latency_ms DOUBLE, source VARCHAR(16),
        sim_true_label VARCHAR(64), top3_json LONGTEXT, features_json LONGTEXT,
        review_state VARCHAR(16) NOT NULL DEFAULT 'unreviewed'
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS alerts (
        id BIGINT AUTO_INCREMENT PRIMARY KEY, prediction_id BIGINT NOT NULL, severity VARCHAR(16), status VARCHAR(16) NOT NULL DEFAULT 'open',
        created_at VARCHAR(24), updated_at VARCHAR(24), handled_by VARCHAR(64)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS feedback (
        id BIGINT AUTO_INCREMENT PRIMARY KEY, prediction_id BIGINT NOT NULL, reviewer VARCHAR(64), verdict VARCHAR(16) NOT NULL,
        original_label VARCHAR(64), final_label VARCHAR(64) NOT NULL, notes LONGTEXT, created_at VARCHAR(24),
        state VARCHAR(16) NOT NULL DEFAULT 'new', used_in_version VARCHAR(32)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE IF NOT EXISTS retrain_runs (
        id BIGINT AUTO_INCREMENT PRIMARY KEY, started_at VARCHAR(24), finished_at VARCHAR(24), triggered_by VARCHAR(64), parent_version VARCHAR(32),
        candidate_version VARCHAR(32), n_feedback_new BIGINT, n_train_new BIGINT, n_val BIGINT,
        status VARCHAR(16), decision VARCHAR(16), reasons_json LONGTEXT, metrics_parent_json LONGTEXT,
        metrics_candidate_json LONGTEXT, error LONGTEXT
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
